// Builds design tokens (DTCG) into CSS custom properties and a flat JSON.
// Generated files are committed; never edit them by hand. `npm run check:tokens` fails on drift.
import StyleDictionary from 'style-dictionary';

const header = 'Generated by tokens/build.mjs from tokens/*.json. Do not edit.';

const sd = new StyleDictionary({
  source: ['tokens/primitive.json', 'tokens/semantic/*.json', 'tokens/component/*.json'],
  log: { verbosity: 'silent' },
  hooks: {
    fileHeaders: { peters: () => [header] },
    formats: {
      'json/peters': ({ dictionary }) =>
        JSON.stringify(
          dictionary.allTokens.map((t) => ({
            name: t.name,
            tier: t.path[0] === 'color' ? 'primitive' : 'semantic',
            group: t.path[0] === 'color' ? t.path[1] : t.path[0],
            value: t.$value ?? t.value,
            ref: typeof t.original.$value === 'string' && t.original.$value.startsWith('{') ? t.original.$value : null,
          })),
          null,
          2,
        ) + '\n',
    },
  },
  platforms: {
    css: {
      transformGroup: 'css',
      transforms: ['name/kebab', 'color/hex'],
      buildPath: 'src/styles/',
      files: [{ destination: 'tokens.css', format: 'css/variables', options: { outputReferences: true, fileHeader: 'peters' } }],
    },
    json: {
      transforms: ['name/kebab', 'color/hex'],
      buildPath: 'tokens/build/',
      files: [{ destination: 'tokens.json', format: 'json/peters' }],
    },
  },
});

await sd.buildAllPlatforms();
console.log('tokens: built src/styles/tokens.css and tokens/build/tokens.json');
